| \`brain-core\` | \`worker.js\` 23,850 + \`lib/hono.js\` 18,838 | rows, blobs, workers |
| \`brain\` (kernel) | \`worker.js\` 22,100 + \`lib/hono.js\` 18,838 + \`lib/atcute.js\` 77,244 | rows, core, guard, assets |
| \`brain-x-proxy\` | \`worker.js\` 9,454 | none |
