}
)};
const _rc5ui_doc = function _rc5_ui_doc(md){return(
md`### Parts of the chat panel

\`robocoop5\` builds one panel and holds its state (the session, whether a turn is running, what is folded). The functions below are the parts of it that keep no state of their own. Each cell is a factory: \`robocoop5\` calls it once with the panel's nodes and palette and gets back the function it used to define inline.

| cell | returns |
|---|---|
| \`rc5_ui_renderContent\` | message content (text and image parts) as DOM |
| \`rc5_ui_bubble\` | one speech bubble |
| \`rc5_ui_activityLine\` | the one-line summary of a tool call |
| \`rc5_ui_renderMsg\` | one message of the transcript, with its branch controls |
| \`rc5_ui_renderThumbs\` | the strip of images waiting to be sent |
| \`rc5_ui_syncResolved\` | the resolved state of a thread, read from its annotation |

Lifted out of \`robocoop5\` on 2026-10-04 without retyping. What is still inline shares mutable state (\`busy\`, \`session\`, \`entry\`, \`folded\`, …) and was left there.`
)};
const _rc5ui_renderContent = function _rc5_ui_renderContent(){return(
() => content => {
    const frag = document.createDocumentFragment();
    if (Array.isArray(content)) {
      for (const p of content) {
        if (p?.type === 'image_url' && p.image_url?.url) {
          const im = document.createElement('img');
          im.src = p.image_url.url;
          im.style.cssText = 'max-width:220px;max-height:160px;border-radius:6px;margin-top:4px;display:block';
          frag.append(im);
        } else if (p?.type === 'text' && p.text) {
          const d = document.createElement('div');
          d.textContent = p.text;
          frag.append(d);
        }
      }
    } else {
      frag.append(document.createTextNode(String(content ?? '')));
    }
    return frag;
  }
)};
const _rc5ui_bubble = function _rc5_ui_bubble(){return(
({ C }) => (side, bgc, node) => {
    const wrap = document.createElement('div');
    wrap.style.cssText = 'display:flex;justify-content:' + (side === 'right' ? 'flex-end' : 'flex-start');
    const b = document.createElement('div');
    b.style.cssText = 'max-width:85%;padding:6px 10px;border-radius:10px;background:' + bgc + ';border:1px solid ' + C.border + ';white-space:normal;overflow-wrap:anywhere';
    b.append(node);
    wrap.append(b);
    return wrap;
  }
)};
const _rc5ui_activityLine = function _rc5_ui_activityLine(toolLabel){return(
({ C }) => calls => {
    const d = document.createElement('div');
    d.style.cssText = 'color:' + C.muted + ';font-size:11.5px;padding:0 4px';
    d.textContent = '\u2699 ' + calls.map(c => {
      let args = c?.function?.arguments;
      try {
        if (typeof args === 'string')
          args = JSON.parse(args);
      } catch {
        args = {};
      }
      return toolLabel(c?.function?.name || 'tool', args);
    }).join('  \xB7  ');
    return d;
  }
)};
const _rc5ui_renderThumbs = function _rc5_ui_renderThumbs(){return(
({ C, pendingImages, thumbs }) => {
  // named, because removing a thumbnail redraws the strip
  const renderThumbs = () => {
    thumbs.innerHTML = '';
    thumbs.style.display = pendingImages.length ? 'flex' : 'none';
    pendingImages.forEach((url, i) => {
      const w = document.createElement('div');
      w.style.cssText = 'position:relative';
      const im = document.createElement('img');
      im.src = url;
      im.style.cssText = 'width:48px;height:48px;object-fit:cover;border-radius:6px;border:1px solid ' + C.border;
      const x = document.createElement('button');
      x.textContent = '\xD7';
      x.title = 'remove';
      x.style.cssText = 'position:absolute;top:-6px;right:-6px;width:18px;height:18px;line-height:15px;border-radius:50%;border:0;background:' + C.err + ';color:#fff;cursor:pointer;font-size:12px;padding:0';
      x.addEventListener('click', () => {
        pendingImages.splice(i, 1);
        renderThumbs();
      });
      w.append(im, x);
      thumbs.append(w);
