const _rc5ui_syncResolved = function _rc5_ui_syncResolved(){return(
({ root, resolveBtn, badge, count, annBox, isResolved }) => () => {
    const box = annBox();
    resolveBtn.style.display = box ? '' : 'none';
    resolveBtn.textContent = isResolved() ? '\u21BA reopen' : '\u2713 resolve';
    badge.style.opacity = isResolved() ? '0.5' : '1';
