const _rc5ui_renderMsg = function _rc5_ui_renderMsg(md){return(
({ C, bubble, renderContent, activityLine, branchControls }) => m => {
    // Injected situational context: shown as a muted collapsible line so the human can audit exactly
    // what the agent was told. Other system messages (nudges, watch updates) stay hidden.
    if (m.role === 'system' && typeof m.content === 'string' && m.content.startsWith('<environment')) {
      const det = document.createElement('details');
      det.style.cssText = 'color:' + C.muted + ';font-size:11.5px;padding:0 4px';
      const sum = document.createElement('summary');
      sum.style.cssText = 'cursor:pointer;list-style-position:inside';
      const scope = /scope="([^"]*)"/.exec(m.content)?.[1] || '';
      sum.textContent = '\u{1F310} context' + (scope ? ' (' + scope + ')' : '');
      const pre = document.createElement('pre');
      pre.style.cssText = 'white-space:pre-wrap;overflow-wrap:anywhere;margin:4px 0 0;color:' + C.muted + ';font-size:11px';
      pre.textContent = m.content;
      det.append(sum, pre);
      return det;
    }
    if (m.role === 'user') {
      const b = bubble('right', C.userMsg, renderContent(m.content));
      const row = branchControls(m);
      if (!row) return b;
      const wrap = document.createElement('div');
      wrap.style.cssText = 'display:flex;flex-direction:column;gap:2px';
      wrap.append(b, row);
      return wrap;
    }
    if (m.role === 'assistant') {
      const parts = [];
      // The step's reasoning, kept on the message (non-enumerable, so never re-sent) and in the turn cell.
      if (typeof m.reasoning === 'string' && m.reasoning) {
        const det = document.createElement('details');
        det.style.cssText = 'color:' + C.muted + ';font-size:11.5px;padding:0 4px;opacity:.85';
        const sum = document.createElement('summary');
        sum.style.cssText = 'cursor:pointer;list-style-position:inside;font-style:italic';
        sum.textContent = '\u{1F4AD} thought ' + m.reasoning.length + ' chars';
        const pre = document.createElement('pre');
        pre.style.cssText = 'white-space:pre-wrap;overflow-wrap:anywhere;margin:4px 0 0;max-height:18em;overflow-y:auto;color:' + C.muted + ';font-size:11px';
        pre.textContent = m.reasoning;
        det.append(sum, pre);
        parts.push(det);
      }
      if (m.content) {
        let node;
        try {
          node = md`${ String(m.content) }`;
        } catch {
          node = document.createTextNode(String(m.content));
        }
        parts.push(bubble('left', C.asst, node));
      }
      if (Array.isArray(m.tool_calls) && m.tool_calls.length)
        parts.push(activityLine(m.tool_calls));
      if (!parts.length)
        return null;
      const wrap = document.createElement('div');
      wrap.style.cssText = 'display:flex;flex-direction:column;gap:4px';
      wrap.append(...parts);
      return wrap;
    }
    return null;  // tool result messages don't show (their effect is the next assistant step)
  }
)};
