const _doc_hooks = function _doc_hooks(md){return(
md`## Hooks

A hook is a named point in a step where rules run. A rule is \`{id, hook, order, check, evidence}\`;
\`check(ctx)\` returns the hook's result type, or null to stay silent. \`runHook(hook, rules, ctx)\`
runs the rules of one hook in ascending \`order\` and composes what they return. The loop below knows
no rule: \`createAgentSession\` takes one function per hook it calls, in \`hooks\`, and the engine builds
each from the registered rules.

| compose | result |
|---|---|
| \`first\` | the first non-null result; later rules do not run |
| \`list\` | every non-null result, arrays flattened |
| \`join\` | the non-null results joined with the hook's \`sep\` |
| \`chain\` | each rule receives the last result as \`ctx.result\`; the final one is returned |

A rule with \`phase: 1\` is evaluated after every rule without one and still placed by its \`order\`: for a
rule whose answer depends on the others having had their time (the value comparison after a write).

\`onThrow\` is \`skip\` (the rule is passed over and the rest run) or \`refuse\` (the hook returns a
refusal naming the rule). \`prompt\` is declared in robocoop-5-engine and \`afterModuleWrite\` in
robocoop-5-srctools, beside the code that calls them.`
)};

const _runHook = function _runHook(){return(
  // Synchronous when every check is: beforeStep runs one statement before the model request and is not awaited.
  function runHook(hook, rules, ctx = {}) {
    const list = (Array.isArray(rules) ? rules : [])
      .filter((r) => r && r.hook === hook.name && typeof r.check === 'function' && !r.defer)
      .map((r, i) => [r, i]).sort((a, b) => ((a[0].order ?? 50) - (b[0].order ?? 50)) || (a[1] - b[1])).map((x) => x[0]);
    // Results are placed by order; a rule with a later `phase` is evaluated after the others.
    const seq = list.map((r, k) => k).sort((a, b) => ((list[a].phase ?? 0) - (list[b].phase ?? 0)) || (a - b));
    const slots = new Array(list.length);
    let cur = ctx, i = 0;
    const refusal = (r, e) => 'REFUSED: rule ' + r.id + ' failed: ' + (e && e.message || e);
    const done = () => {
      if (hook.compose === 'first') return null;
      if (hook.compose === 'chain') return cur.result;
      const out = slots.flat().filter((x) => x != null);
      return hook.compose === 'list' ? out : out.join(hook.sep ?? '');
    };
    // [value] stops the hook; undefined goes on to the next rule
    const take = (res, k) => {
      if (res == null || res === '') return;
      if (hook.compose === 'first') return [res];
      if (hook.compose === 'chain') cur = { ...cur, result: res };
      else slots[k] = res;
    };
    const step = () => {
      while (i < seq.length) {
        const k = seq[i++], r = list[k];
        let res;
        try { res = r.check(cur); } catch (e) { if (hook.onThrow === 'refuse') return refusal(r, e); continue; }
        if (res && typeof res.then === 'function')
          return res.then((v) => { const s = take(v, k); return s ? s[0] : step(); },
            (e) => hook.onThrow === 'refuse' ? refusal(r, e) : step());
        const s = take(res, k);
        if (s) return s[0];
      }
      return done();
    };
    return step();
  }
)};

