    const armed = typeof a2Layer.isArmed === "function" && a2Layer.isArmed();
    const armedKind = typeof a2Layer.armedKind === "function" ? a2Layer.armedKind() : null;
    const kinds = a2KindsRef.all();
    return [
      ...kinds.map((k, i) => ({
        label: k.id === "note" ? "\uD83D\uDCAC Annotate" : (k.icon || "\uD83D\uDCAC") + " Annotate: " + k.label,
