  // The source omits `xmlns` because svg`…` already parses in the SVG namespace; a standalone file is
  // parsed as plain XML, so without it the root element lands in no namespace and viewers show nothing.
  const standalone = (t) => {
    if (!t || !/^<svg[\s/>]/i.test(t)) return t || "";
