svg\`<svg>…\`                                       // the default editor (svg is svgLens())
svgLens({ tools: [toolVertex] })\`<svg>…\`          // a vertex-only editor
svgLens({ tools: (d) => [myTool, ...d] })\`<svg>…\` // extend without restating the defaults
svgLens({ tools: [toolMove], affordances: [] })\`<svg>…\` // a bare drawing: handles, no chips
