@tomlarkworthy/robocoop-5-context:
// @tomlarkworthy/robocoop-5-context — tier-1 situational context providers for robocoop-5.
//
// Each provider is a plain object {id, label, scope, priority, budget, weak, render} registered into
// the 'rc5-context' plugin set (robocoop-5-tools). The engine composes them into an <environment>
// block at each turn via composeContext (robocoop-5-core). Providers are DOM-first: they read browser
// globals and DOM conventions (.lp2-pane, .observablehq[cell]) rather than other modules' cells, so
// the module works in any host and degrades to silence headlessly. Providers that scrape what a
// richer owner (e.g. lopepage-2) could publish are marked weak:true so an owner-registered provider
// displaces them regardless of boot order.

const _intro = function _intro(md){return(
md`# robocoop-5-context
Tier-1 situational context for [robocoop-5](/@tomlarkworthy/robocoop-5): what time it is, what page
this is, which panes and cells are on screen, the current selection, recent code edits, and cells
erroring at runtime. Registered under the \`rc5-context\` plugin set; any notebook can add its own
provider with \`registerContext({id, label, scope, priority, budget, render})\` to teach the agent
about *its* document. The \`get_context\` tool re-runs the providers mid-turn.`
)};

const _ctx_sanitizeUrl = function _ctx_sanitizeUrl(){return(
  // Strip credential-ish query/hash params (pairing tokens ride the hash as cc=LOPE-…) before a URL
  // reaches a third-party model. Values are replaced with …, structure kept. Over-stripping is safe.
  (href) => String(href ?? '').replace(
    /([?&#])([^=&#]*(?:cc|token|key|secret|auth|password|sig)[^=&#]*)=[^&#]*/gi,
    '$1$2=…'
  )
)};

const _ctx_clock = function _ctx_clock()
{
  let lastAt = null;
  return {
    id: 'clock',
    label: 'Time',
    scope: 'turn',
    priority: 10,
    budget: 160,
    render: ({now}) => {
      const t = now.getTime();
      const day = ['Sun','Mon','Tue','Wed','Thu','Fri','Sat'][now.getDay()];
      let tz = '';
      try { tz = Intl.DateTimeFormat().resolvedOptions().timeZone || ''; } catch (e) {}
      const offMin = -now.getTimezoneOffset();
      const off = 'UTC' + (offMin >= 0 ? '+' : '-') + Math.floor(Math.abs(offMin) / 60) + (Math.abs(offMin) % 60 ? ':' + String(Math.abs(offMin) % 60).padStart(2, '0') : '');
      let gap = '';
      if (lastAt != null) {
        const s = Math.round((t - lastAt) / 1000);
        gap = ' · ' + (s < 60 ? s + 's' : s < 3600 ? Math.round(s / 60) + 'm' : Math.round(s / 3600) + 'h') + ' since previous turn';
      }
      lastAt = t;
      return day + ' ' + (tz ? tz + ' (' + off + ')' : off) + gap;
    }
  };
};

const _ctx_page = function _ctx_page(ctx_sanitizeUrl){return(
  {
    id: 'page',
    label: 'Page',
    scope: 'session',
    priority: 5,
    budget: 300,
    render: () => {
      if (typeof document === 'undefined') return null;
      const title = document.title || '(untitled)';
      const url = ctx_sanitizeUrl(typeof location !== 'undefined' ? location.href : '');
      return title + (url ? '\n' + url : '');
    }
  }
)};

const _ctx_notebook = function _ctx_notebook(runtime){return(
  {
    id: 'notebook',
    label: 'Notebook',
    scope: 'session',
    priority: 10,
    budget: 500,
    render: () => {
      if (typeof document === 'undefined') return null;
      let mains = [];
      try {
        const b = document.getElementById('bootconf.json');
        if (b) mains = JSON.parse(b.textContent).mains || [];
      } catch (e) {}
      const mods = [...document.querySelectorAll('script[type="text/plain"][data-mime="application/javascript"]')].map((s) => s.id);
      if (!mains.length && !mods.length) return null;
      // bootconf is the file as loaded; modules created or seeded since are only in the live mains
      try { mains = [...new Set([...mains, ...runtime.mains.keys()])]; } catch (e) {}
      // a module block the file carries that nothing boots or imports: saved once, never in mains, so it does not open.
      // Attachment owners are skipped: 180 corpus files carry an unused golden-layout-2-6-0 library block.
      let orphans = [];
      try {
        const loaded = new Set(mains);
        for (const v of runtime._variables) if (typeof v._name === 'string' && v._name.startsWith('module ') && v._value) loaded.add(v._name.slice(7));
        const blocks = [...document.querySelectorAll('script[type="text/plain"][id]')];
        orphans = mods.filter((id) => /^@[^/]+\/[^/]+$/.test(id) && !loaded.has(id) && id !== '@tomlarkworthy/bootloader' &&
          !blocks.some((b) => b.id !== id && (b.id.startsWith(id + '/') || (b.textContent || '').includes(id))));
      } catch (e) {}
      const lines = [];
      // the host's own mains: the chat (robocoop-5*) and its page chrome. The rest is the user's work.
      // A chat log (a module with a session_meta cell) is in mains under the chat's own group, not the user's
      // namespace; listed as the user's, the agent named new modules @robocoop5-session/… and eval'd in the log.
      const logs = new Set();
      try {
        const withMeta = new Set();
        for (const v of runtime._variables) if (v._name === 'session_meta') withMeta.add(v._module);
        for (const [n, m] of runtime.mains) if (withMeta.has(m)) logs.add(n);
      } catch (e) {}
      const host = (m) => logs.has(m) || /^@tomlarkworthy\/(robocoop-5|lopepage|save-in-place$|inputs-reference$)/.test(m);
      if (mains.length) {
        const own = mains.filter((m) => !host(m));
        lines.push("the user's modules (\"my notebook\" means these): " + (own.join(', ') || (orphans.length ? 'none booted' : 'none yet')));
        if (orphans.length) lines.push("also the user's, saved in this file but NOT booted — absent from bootconf.json mains and imported by nothing, so the page opens without them: " +
          orphans.map((id) => id + ' (source: /content/' + id + ')').join(', ') +
          '. Boot one unchanged, without retyping it: write_file {file_path: "/src/<id>.js", from: "/content/<id>"}');
        lines.push("the chat you run in (not the user's notebook): " + mains.filter(host).join(', '));
      }
      if (mods.length) lines.push(mods.length + ' modules bundled (glob /src/**/*.js to list; read one as a template)');
      return lines.join('\n');
    }
  }
)};

const _ctx_layout = function _ctx_layout(){return(
  // weak: lopepage-2 (or another host) can register a richer 'layout' from its real model.
  {
    id: 'layout',
    label: 'Layout',
    scope: 'turn',
    priority: 20,
    budget: 1100,
    weak: true,
    render: () => {
      if (typeof document === 'undefined') return null;
      const panes = [...document.querySelectorAll('.lp2-pane[data-module]')];
      if (!panes.length) return null;
      let focused = null;
      try { focused = document.activeElement?.closest?.('.lp2-pane')?.dataset?.module || null; } catch (e) {}
      let view = '';
      try { view = new URLSearchParams(location.hash.slice(1)).get('view') || ''; } catch (e) {}
      // where each pane is on screen: a stack keeps its other tabs in the DOM with display:none
      const W = innerWidth, H = innerHeight;
      let chatShown = false;
      const names = panes.map((p) => {
        const m = p.dataset.module;
        if (!/^@[^/(),]+\/[^/(),]+$/.test(m)) return m + ': NOT a module — the layout is malformed (S(...) holds module names only)';
        const r = p.getBoundingClientRect();
        const shown = (p.checkVisibility ? p.checkVisibility() : p.offsetParent !== null) && r.width > 0 && r.height > 0;
        if (shown && /^@tomlarkworthy\/robocoop-5/.test(m)) chatShown = true;
        return m + (m === focused ? ' (focused)' : '') + (shown
          ? ': shown x ' + Math.round(r.left) + '-' + Math.round(r.right) + ' y ' + Math.round(r.top) + '-' + Math.round(r.bottom)
          : ': HIDDEN (a background tab of its stack)');
      });
      return 'viewport ' + W + 'x' + H + '\npanes:\n' + names.map((n) => '- ' + n).join('\n') +
        (chatShown ? '' : '\nthe chat (@tomlarkworthy/robocoop-5) is not shown in this layout') +
        (view ? '\nlayout: ' + view +
        '\ngrammar: R(a,b) = side by side, left to right. C(a,b) = top to bottom. S(a,b) = TABS, only one shows. R and C nest; S(...) holds module names only. Numbers are % weights. Example: R100(C50(S50(@a/x),S50(@a/y)),S50(@a/z)) = x above y on the left, z on the right.' +
        '\na save writes this layout and runtime.mains into the file; reopened, each S(...) stack shows only its FIRST tab. Change it with eval_js: location.hash = "#view=…"; then read get_context layout to check the pane positions.' : '');
    }
  }
)};

const _ctx_viewport = function _ctx_viewport(){return(
  // What the human can actually see: per visible pane, the cells whose boxes intersect the visible
  // band (same offsetTop/scrollTop geometry lp2_anchor uses). weak: a host can do better.
  {
    id: 'viewport',
    label: 'On screen',
    scope: 'turn',
    priority: 25,
    budget: 500,
    weak: true,
    render: () => {
      if (typeof document === 'undefined') return null;
      const panes = [...document.querySelectorAll('.lp2-pane')];
      if (!panes.length) return null;
      const lines = [];
      for (const pane of panes) {
        if (!pane.clientHeight || pane.offsetParent === null) continue;   // hidden tab
        const top = pane.scrollTop, bot = top + pane.clientHeight;
        const labels = [];
        for (const node of pane.querySelectorAll('.observablehq[cell]')) {
          const nTop = node.offsetTop, nBot = nTop + node.offsetHeight;
          if (nBot <= top || nTop >= bot) continue;
          let label = null;
          try { label = node.variable?._name || null; } catch (e) {}
          if (!label) {
            const h = node.querySelector('h1,h2,h3');
            if (h) label = '§ ' + String(h.textContent).trim().slice(0, 40);
          }
          if (label && !labels.includes(label)) labels.push(label);
          if (labels.length >= 8) break;
        }
        if (!labels.length) continue;
        const max = pane.scrollHeight - pane.clientHeight;
        const pct = max > 0 ? ' · scrolled ' + Math.round(pane.scrollTop / max * 100) + '%' : '';
        lines.push((pane.dataset.module || 'pane') + pct + ': ' + labels.join(', '));
      }
      return lines.length ? lines.join('\n') : null;
    }
  }
)};

const _ctx_selection = function _ctx_selection(){return(
  {
    id: 'selection',
    label: 'Selection',
    scope: 'turn',
    priority: 30,
    budget: 260,
    render: () => {
      if (typeof document === 'undefined') return null;
      let sel = '';
      try { sel = String(window.getSelection?.() ?? '').trim(); } catch (e) {}
      if (!sel) return null;
      return 'user has selected: "' + sel.slice(0, 200) + (sel.length > 200 ? '…' : '') + '"';
    }
  }
)};

const _ctx_edits = function _ctx_edits(onCodeChange,runtime,invalidation)
{
  // Delta provider: must record as it happens. Boot floods onCodeChange — an added event for every
  // variable the runtime creates AND changed events as import edges redefine — so nothing is
  // recorded until the page has settled. Latest event per module:cell wins; render() drains what is
  // new since the previous turn.
  const buf = new Map();
  const started = Date.now();
  const moduleName = (mod) => {
    try {
      if (runtime.mains) for (const [name, m] of runtime.mains) if (m === mod) return name;
    } catch (e) {}
    return null;
  };
  const un = onCodeChange(({variable, previous, t}) => {
    const name = (variable && variable._name) || (previous && previous._name);
    if (!name || String(name).startsWith('module ')) return;
    if (t - started < 15000) return;   // boot flood (adds and import-edge redefinitions)
    const isNew = !previous;
    const mod = (variable && variable._module) || (previous && previous._module);
    const mn = moduleName(mod);
    const kind = !variable ? 'removed' : isNew ? 'added' : 'changed';
    buf.set((mn || '?') + ':' + name, { t, kind, module: mn, name });
  });
  invalidation.then(() => { try { un(); } catch (e) {} });
  let lastDrainAt = 0;
  return {
    id: 'edits',
    label: 'Recent code edits',
    scope: 'turn',
    priority: 15,
    budget: 400,
    render: () => {
      const nowT = Date.now();
      for (const [k, e] of buf) if (nowT - e.t > 3600000) buf.delete(k);   // prune >1h
      const fresh = [...buf.values()].filter((e) => e.t > lastDrainAt).sort((a, b) => a.t - b.t);
      lastDrainAt = nowT;
      if (!fresh.length) return null;
      const ago = (t) => { const s = Math.round((nowT - t) / 1000); return s < 60 ? s + 's ago' : Math.round(s / 60) + 'm ago'; };
      const shown = fresh.slice(-8);
      return shown.map((e) => e.kind + ' ' + (e.module ? e.module + ' → ' : '') + e.name + ' (' + ago(e.t) + ')').join('\n') +
        (fresh.length > shown.length ? '\n… ' + (fresh.length - shown.length) + ' more' : '');
    }
  };
};

const _ctx_health = function _ctx_health(){return(
  {
    id: 'health',
    label: 'Erroring cells',
    scope: 'turn',
    priority: 12,
    budget: 400,
    render: () => {
      if (typeof document === 'undefined') return null;
      const errs = [...document.querySelectorAll('.observablehq--error')];
      if (!errs.length) return null;
      const lines = [];
      for (const node of errs.slice(0, 6)) {
        let name = null;
        try { name = node.variable?._name || null; } catch (e) {}
        const mod = node.closest?.('.lp2-pane')?.dataset?.module || null;
        const msg = String(node.textContent || '').replace(/\s+/g, ' ').trim().slice(0, 90);
        lines.push((mod ? mod + ' → ' : '') + (name || '(cell)') + ': ' + msg);
      }
      if (errs.length > 6) lines.push('… ' + (errs.length - 6) + ' more');
      return lines.join('\n');
    }
  }
)};

const _defaultWatches = function _defaultWatches(runtime){return(
// The watches a chat starts with (robocoop5({ watches })). Each call returns fresh specs, because a polled
// watch keeps state. The first step sees each value in full, later steps only what changed.
//   modules         every named module the runtime holds -> 'main' when it is in runtime.mains (saved)
//   erroring cells  every computed cell whose last run threw, anywhere in the runtime, on screen or not;
//                   cells that failed only because an input failed are counted onto that input
() => {
  const names = () => {
    const byMod = new Map();
    const mains = runtime.mains ?? new Map();
    for (const [n, m] of mains) byMod.set(m, n);
    for (const v of runtime._variables) {
      const n = v._name;
      // an Observable-compiled notebook names its imports by index ("module 6"); the module is named elsewhere
      if (typeof n === 'string' && n.startsWith('module ') && !/^module \d+$/.test(n) && v._value?._scope && !byMod.has(v._value))
        byMod.set(v._value, n.slice(7));
    }
    return { byMod, mains };
  };
  const modules = () => {
    const { byMod, mains } = names();
    const live = new Set();
    for (const v of runtime._variables) if (v._module && v._module !== runtime._builtin) live.add(v._module);
    const out = {};
    for (const m of live) {
      const n = byMod.get(m);
      if (n) out[n] = mains.get(n) === m ? 'main' : '';
    }
    return out;
  };
  const seen = new WeakMap();  // variable -> the promise last subscribed to
  const failed = new Map();    // variable -> error of its current promise
  const sweep = () => {
    for (const v of runtime._variables) {
      if (v._type !== 1) continue;
      const p = v._promise;
      if (!p || seen.get(v) === p) continue;
      seen.set(v, p);
      failed.delete(v);
      p.then(() => { if (v._promise === p) failed.delete(v); }, e => { if (v._promise === p) failed.set(v, e); });
    }
  };
  const errors = () => {
    sweep();
    for (const v of failed.keys()) if (!runtime._variables.has(v)) failed.delete(v);
    const { byMod } = names();
    const out = {};
    // a dependent rejects with its input's error; compare messages, the runtime may not keep the object
    const msg = e => String(e?.message ?? e);
    const downstream = v => v._inputs.some(i => failed.has(i) && msg(failed.get(i)) === msg(failed.get(v)));
    for (const [v, e] of failed) {
      if (downstream(v)) continue;
      let n = 0;
      for (const [w, f] of failed) if (w !== v && msg(f) === msg(e) && downstream(w)) n++;
      const key = (byMod.get(v._module) ?? '?') + ':' + (v._name ?? (v.pid ? 'pid ' + v.pid : '(anonymous)'));
      out[key] = msg(e).slice(0, 100) + (n ? ' [+' + n + ' downstream]' : '');
    }
    return out;
  };
  sweep();
  return [
    { label: 'modules', read: modules, limit: 4000 },
    { label: 'erroring cells', read: errors }
  ];
}
)};

const _get_context = function _get_context(defineTool,contextView,composeContext){return(
  defineTool({
    id: 'get_context',
    description: 'Refresh the situational <environment> snapshot MID-TURN: re-runs the registered context ' +
