const _rs_test_controller = async function _test_session_controller(createSessionController,disposeSession,runtime,expect){
  const fake = () => {
    const messages = [];
    return { messages, async send(input) {
      if (input === "boom") throw new Error("boom");
      messages.push({ role: "user", content: input }, { role: "assistant", content: "re: " + input });
    } };
  };
  const a = createSessionController({ runtime });
  const e = await a.use(a.create({ group: "rc5-test" }), fake);
  let logs = [];
  try {
    await a.send(e, "hello there");
    await expect(a.send(e, "boom")).rejects.toThrow("boom");
    expect(e.title).toBe("hello there");
    expect(e.log).toBeTruthy();
    logs.push(e.log);
    await a.setSaved(e, true);
    expect([...runtime.mains.keys()]).toContain("@rc5-test/" + e.log.meta.id);
    // a fresh controller stands in for a reload: it finds the session by reflection and resumes it
    const b = createSessionController({ runtime });
    await b.refresh();
    const found = b.entries.find(x => x.log.module === e.log.module);
    expect(found.saved).toBe(true);
    expect(found.group).toBe("rc5-test");
    expect(found.session).toBe(null);
    await b.use(found, fake);
    expect(found.session.messages).toEqual([
      { role: "user", content: "hello there" }, { role: "assistant", content: "re: hello there" }
    ]);
    // a different builder (another chat, or a new makeSession) swaps the agent and keeps the transcript
    const other = () => fake();
    const before = found.session;
    await b.use(found, other);
    expect(found.session).not.toBe(before);
    expect(found.session.messages.length).toBe(2);
    // the failed send committed nothing (it pushed no messages) and did not break the next one
    await b.send(found, "second");
    expect(found.session.messages.length).toBe(4);
    // edit-and-resend: back up to before "second", send something else -> a sibling branch
    const second = found.session.messages[2];
    const secondId = b.nodeOf(second);
    await b.forkBefore(found, second);
    expect(found.session.messages.map(m => m.content)).toEqual(["hello there", "re: hello there"]);
    await new Promise(r => window.setTimeout(r, 5));
    await b.send(found, "third");
    const thirdId = found.head;
    expect(b.siblings(found, thirdId)).toEqual([secondId, thirdId]);
    // a reload opens the latest branch; the older one is still one step away
    const c = createSessionController({ runtime });
    await c.refresh();
    const again = c.entries.find(x => x.log.module === e.log.module);
    await c.use(again, fake);
    expect(again.session.messages.map(m => m.content)).toEqual(["hello there", "re: hello there", "third", "re: third"]);
    await c.showBranch(again, secondId);
    expect(again.session.messages.map(m => m.content)).toEqual(["hello there", "re: hello there", "second", "re: second"]);
    return "create in a group, commit on settle, save as @group/id, rediscover, resume, swap agent, fork, reopen at latest, switch branch";
  } finally {
    for (const l of logs) disposeSession(l);
  }
};
const _rs_test_open = async function _test_session_controller_open_by_id(createSessionController,runtime,expect){
  const fake = () => {
    const messages = [];
    return { messages, async send(input) { messages.push({ role: "user", content: input }, { role: "assistant", content: "re: " + input }); } };
  };
  const group = "rc5-open-test", id = "t" + Math.random().toString(36).slice(2, 8);
