// this for its agents through the beforeTool and afterTool hooks; this is the same thing for a caller that
// holds tools and no session.
(() => {
  const cache = new WeakMap();
  const noHooks = {};
  const wrap = (tool, hooks) => ({
    ...tool,
    execute: async (args, ctx) => {
      const why = rule_beforeTool_self_edit.check({ name: tool.id, args }) ?? (hooks.beforeTool?.({ name: tool.id, args }) || null);
